// ✅ Zero allocation with Span
public void ParseWithSpan(ReadOnlySpan<char> input)
{
    var reader = new SpanReader(input);
    while (!reader.IsEnd)
    {
        var item = reader.ReadUntil(',');
        ProcessItem(item); // item is a span, no allocation
    }
}

public ref struct SpanReader
{
    private ReadOnlySpan<char> _input;
    private int _position;

    public SpanReader(ReadOnlySpan<char> input)
    {
        _input = input;
        _position = 0;
    }

    public ReadOnlySpan<char> ReadUntil(char delimiter)
    {
        var start = _position;
        while (_position < _input.Length && _input[_position] != delimiter)
        {
            _position++;
        }
        var result = _input.Slice(start, _position - start);
        _position++; // Skip delimiter
        return result;
    }
}

