public class PagedBuffer : IMemoryOwner<byte>, IDisposable
{
    private readonly List<byte[]> _pages = new();
    private int _length;

    public PagedBuffer(int initialCapacity)
    {
        var pageSize = 4096;
        var pageCount = (initialCapacity + pageSize - 1) / pageSize;
        for (int i = 0; i < pageCount; i++)
        {
            _pages.Add(new byte[pageSize]);
        }
    }

    public Memory<byte> Memory => new PagedMemory(_pages, _length);

    public void Dispose()
    {
        foreach (var page in _pages)
        {
            ArrayPool<byte>.Shared.Return(page);
        }
        _pages.Clear();
    }
}

